import React, { useEffect } from 'react';
import { FiDownload } from 'react-icons/fi';

export default function POPrintClassic({ poData, vendor, onClose, autoPrint = false }) {
  const handlePrint = () => window.print();

  useEffect(() => {
    if (autoPrint) {
      const t = setTimeout(() => window.print(), 120);
      return () => clearTimeout(t);
    }
  }, [autoPrint]);

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      maximumFractionDigits: 2,
      minimumFractionDigits: 2,
    }).format(Number(amount || 0));
  };

  const items = Array.isArray(poData?.items) ? poData.items : [];
  const totalQty = items.reduce((s, it) => s + (Number(it.quantity) || 0), 0);
  const rowAmount = (it) => (Number(it.quantity || 0) * Number(it.unitPrice || it.rate || 0));
  const subTotal = items.reduce((s, it) => s + rowAmount(it), 0);
  const gstPct = Number(poData?.gstPercent ?? poData?.gst ?? 18);
  const totalGst = items.reduce((s, it) => {
    const p = Number(it.gstPercent ?? it.gst ?? gstPct);
    return s + (rowAmount(it) * (p / 100));
  }, 0);
  const sgst = totalGst / 2;
  const cgst = totalGst / 2;
  const grandTotal = subTotal + totalGst;

  const formatDate = (val) => {
    try {
      if (!val) return '';
      let d = val;
      if (typeof val?.toDate === 'function') d = val.toDate();
      else if (typeof val === 'string') d = new Date(val);
      return d.toLocaleDateString('en-IN', { day: '2-digit', month: '2-digit', year: 'numeric' });
    } catch { return ''; }
  };
  const toRupees = (n) => `₹ ${formatCurrency(n)}`;

  return (
    <div className="print-overlay fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg max-w-5xl w-full max-h-[90vh] overflow-y-auto">
        <style>{`
          @media print {
            @page { size: A4 portrait; margin: 10mm 12mm 15mm 12mm; }
            body { -webkit-print-color-adjust: exact; print-color-adjust: exact; background: #fff !important; }
            * { background: transparent !important; box-shadow: none !important; text-shadow: none !important; }
            body * { visibility: hidden !important; }
            .print-overlay, .print-overlay * { visibility: visible !important; }
            .print-overlay { position: static !important; inset: auto !important; padding: 0 !important; background: transparent !important; overflow: visible !important; }
            .print-overlay > div { width: 210mm !important; max-width: none !important; max-height: none !important; height: auto !important; overflow: visible !important; border-radius: 0 !important; box-shadow: none !important; }
            html, body { overflow: visible !important; height: auto !important; width: 210mm !important; margin: 0 !important; padding: 0 !important; }
            #po-classic-preview { width: 100% !important; margin: 0 !important; padding: 0 !important; }
            .no-print { display: none !important; }
            .brand-logo { max-height: 12mm !important; width: auto !important; height: auto !important; }
            .print-a4 { box-shadow: none !important; margin: 0 !important; padding: 0 !important; }
            thead { display: table-header-group; }
            tfoot { display: table-row-group; }
            tr, td, th { page-break-inside: avoid; }
          }
          .print-a4 { max-width: 210mm; margin: 18px auto; background: white; font-family: 'Inter', 'Helvetica','Arial',sans-serif; line-height: 1.5; color: #0f172a; font-size: 12.5px; }
          .company-header { border-bottom: 1px solid #d1d5db; padding-bottom: 10px; margin-bottom: 14px; display:flex; justify-content:space-between; align-items:flex-start; }
          .company-title { font-size: 19px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.5px; }
          .brand-logo { max-height: 70px; width: auto; height: auto; object-fit: contain; }
          .po-title { text-align:center; font-weight:800; font-size:16px; margin: 8px 0 12px; letter-spacing: 0.3px; }
          .two-col { display:grid; grid-template-columns: 1fr 1fr; gap: 18px; margin: 6px 0 12px; }
          .box { padding: 0; border: none; }
          .muted { color:#475569; }
          .table { width:100%; border-collapse: collapse; margin-top: 10px; }
          .table thead th { background:#f8fafc; border:1px solid #d1d5db; padding:7px 8px; font-size:11px; text-align:left; letter-spacing: .2px; color: #334155; }
          .table tbody td { border:1px solid #e2e8f0; padding:6px 8px; font-size:11px; vertical-align:top; }
          .table tbody tr:nth-child(even) { background:#fafafa; }
          .table td:nth-child(7), .table td:nth-child(8), .table td:nth-child(9), .table tfoot td { text-align: right; }
          .table th:nth-child(7), .table th:nth-child(8), .table th:nth-child(9) { text-align: right; }
          .totals { display:grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 14px; }
          .totals .right td { border: none; padding: 4px 6px; }
          .totals .row { display:flex; justify-content:space-between; padding: 6px 8px; border-bottom:1px dashed #cbd5e1; }
          .totals .row.total { background:#111827; color:#fff; font-weight:800; border-radius: 6px; padding: 8px 10px; }
          .footer { margin-top: 18px; font-size:11px; text-align:center; color:#64748b; }
        `}</style>

        <div className="p-4 border-b border-gray-200 flex justify-between items-center no-print">
          <h2 className="text-xl font-semibold text-gray-900">Print Purchase Order (Classic)</h2>
          <div className="flex gap-2">
            <button onClick={handlePrint} className="inline-flex items-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">
              <FiDownload className="mr-2" size={16} /> Print / Save PDF
            </button>
            <button onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50">Close</button>
          </div>
        </div>

        <div className="print-a4 p-10" id="po-classic-preview">
          {/* Header */}
          <div className="company-header">
            <div>
              <div className="company-title">THORAT FLOW CONTROLS PVT. LTD.</div>
              <div>M. No-1373, Sawantpur Vashat, Palus, Dist. Sangli, Pin Code-416310</div>
              <div>Email: valves@thoratflowcontrols.com</div>
              <div>GSTIN: 27AALCT6867N1Z8</div>
              <div>State: 27-Maharashtra</div>
            </div>
            <div>
              <img src={process.env.PUBLIC_URL + '/thorat-logo.png'} alt="THORAT" className="brand-logo" />
            </div>
          </div>

          <div className="po-title">Purchase Order</div>

          {/* Order To + Order Details */}
          <div className="two-col">
            <div className="box">
              <div className="font-semibold mb-2">Order To</div>
              <div className="font-semibold">{vendor?.name || '-'}</div>
              <div className="whitespace-pre-line">{vendor?.address || '-'}</div>
              {vendor?.phone ? (<div>Contact No.: {vendor.phone}</div>) : null}
              {vendor?.gstin || vendor?.gst ? (<div>GSTIN Number: {vendor?.gstin || vendor?.gst}</div>) : null}
              <div>State: {vendor?.state || '27-Maharashtra'}</div>
            </div>
            <div className="box">
              <div className="font-semibold mb-2">Order Details</div>
              <div>Order No.: <strong>{poData?.poNumber || '-'}</strong></div>
              <div>Date: <strong>{formatDate(poData?.createdAt) || formatDate(new Date())}</strong></div>
              <div>Place of Supply: {poData?.placeOfSupply || '27-Maharashtra'}</div>
            </div>
          </div>

          {/* Items Table */}
          <table className="table">
            <thead>
              <tr>
                <th style={{width:'4%'}}>#</th>
                <th style={{width:'32%'}}>Item name</th>
                <th style={{width:'18%'}}>Operations</th>
                <th style={{width:'8%'}}>HSN/ SAC</th>
                <th style={{width:'8%'}}>Quantity</th>
                <th style={{width:'8%'}}>Unit</th>
                <th style={{width:'11%'}}>Price/ Unit</th>
                <th style={{width:'5%'}}>GST</th>
                <th style={{width:'6%'}}>Amount</th>
              </tr>
            </thead>
            <tbody>
              {items.map((it, i) => {
                const amount = rowAmount(it);
                const p = Number(it.gstPercent ?? it.gst ?? gstPct);
                const gstAmt = amount * (p/100);
                const ops = Array.isArray(it.operations) ? it.operations : (it.operation ? [it.operation] : []);
                return (
                  <tr key={i}>
                    <td>{i + 1}</td>
                    <td>
                      <div className="font-medium">{it.description || it.name || ''}</div>
                      {it.specifications ? (<div className="text-xs text-gray-700 mt-1">{it.specifications}</div>) : null}
                    </td>
                    <td>{ops.length ? ops.join(', ') : '-'}</td>
                    <td>{it.hsn || it.hsnSac || '-'}</td>
                    <td>{it.quantity || 0}</td>
                    <td>{it.unit || it.uom || 'Nos'}</td>
                    <td className="text-right">{toRupees(it.unitPrice || it.rate || 0)}</td>
                    <td>
                      {toRupees(gstAmt)}
                      <div className="text-[10px] muted">({p}% )</div>
                    </td>
                    <td className="text-right">{toRupees(amount)}</td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot>
              <tr>
                <td colSpan={4} className="text-right font-bold">Total</td>
                <td className="font-bold">{totalQty}</td>
                <td></td>
                <td></td>
                <td className="text-right">{toRupees(totalGst)}</td>
                <td className="text-right font-bold">{toRupees(subTotal)}</td>
              </tr>
            </tfoot>
          </table>

          {/* Description + Totals */}
          <div className="totals">
            <div className="box">
              <div className="font-semibold mb-2">Description</div>
              <div className="whitespace-pre-line text-sm">{poData?.notes || poData?.description || '—'}</div>
              <div className="mt-3 font-semibold">Order Amount In Words</div>
              <div className="text-sm">{poData?.amountInWords || '—'}</div>
              <div className="mt-3 font-semibold">Terms And Conditions</div>
              <div className="text-sm whitespace-pre-line">{poData?.terms || '-'}</div>
            </div>
            <div className="box">
              <table className="w-full text-sm right">
                <tbody>
                  <tr>
                    <td>Sub Total</td>
                    <td className="text-right">{toRupees(subTotal)}</td>
                  </tr>
                  <tr>
                    <td>SGST@{(gstPct/2).toFixed(1)}%</td>
                    <td className="text-right">{toRupees(sgst)}</td>
                  </tr>
                  <tr>
                    <td>CGST@{(gstPct/2).toFixed(1)}%</td>
                    <td className="text-right">{toRupees(cgst)}</td>
                  </tr>
                  <tr>
                    <td className="row total" colSpan={2}>
                      <span>Total</span>
                      <span>{toRupees(grandTotal)}</span>
                    </td>
                  </tr>
                  <tr>
                    <td>Advance</td>
                    <td className="text-right">{toRupees(poData?.advance || 0)}</td>
                  </tr>
                  <tr>
                    <td>Balance</td>
                    <td className="text-right">{toRupees(grandTotal - Number(poData?.advance || 0))}</td>
                  </tr>
                </tbody>
              </table>
              <div className="mt-10 text-right font-semibold">For: THORAT FLOW CONTROLS PVT. LTD.</div>
            </div>
          </div>

          <div className="mt-12 text-center font-semibold">Authorized Signatory</div>

          
        </div>
      </div>
    </div>
  );
}
